                    sibling_partial += __shfl_down_sync(MASK, sibling_partial, 4);
                    sibling_partial += __shfl_down_sync(MASK, sibling_partial, 2);
                    sibling_partial += __shfl_down_sync(MASK, sibling_partial, 1);
